\set ON_ERROR_STOP on
CREATE ROLE anon;
CREATE ROLE authenticated;
CREATE ROLE service_role;
CREATE SCHEMA auth;
CREATE FUNCTION auth.uid() RETURNS uuid LANGUAGE sql AS $$SELECT NULL::uuid$$;
CREATE TABLE unions(id uuid PRIMARY KEY);
CREATE TABLE union_settlement_floor(union_id uuid,earliest_period_start timestamptz);
CREATE TABLE union_settlement_rounds(union_id uuid,period_start timestamptz,period_end timestamptz,round_no int,round_name text,payers int,payees int,amount numeric,shortfalls int,detail jsonb,UNIQUE(union_id,period_start,period_end,round_no));
CREATE TABLE settlement_locks(lock_type text,is_active boolean);
CREATE TABLE union_rake_rollup_days(union_id uuid,day date);
CREATE TABLE rakeback_periods(club_id uuid,period_start date,period_end date,status text,rakeback_amount numeric);
CREATE TABLE union_clubs(union_id uuid,club_id uuid);
CREATE TABLE settlement_invoices(club_id uuid,invoice_type text,breakdown jsonb,message_sent boolean,status text);
CREATE TABLE financial_alerts(source text,severity text,message text,context jsonb);
CREATE TABLE ca_money_rpc_registry(proname text PRIMARY KEY,status text,notes text);
CREATE TABLE fixture(stage integer PRIMARY KEY,result jsonb);
CREATE TABLE effects(stage integer,amount numeric);
INSERT INTO fixture VALUES(1,'{"success":true,"period_rake":100,"total_rakeback":90,"union_retained":10}'),(2,'{"amount":50,"payees":1,"shortfalls":0}'),(3,'{"amount":25,"payees":1,"shortfalls":0}'),(4,'{"success":true,"invoices":1}');
CREATE FUNCTION fn_caller_is_engine() RETURNS boolean LANGUAGE sql AS $$SELECT COALESCE(current_setting('test.is_engine',true),'true')::boolean$$;
CREATE FUNCTION fn_is_union_overseer(uuid,uuid) RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION ca_can_oversee_union(uuid) RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION fn_platform_frozen() RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION fn_is_platform_admin() RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION fn_union_rake_rollup_refresh_day(uuid,date) RETURNS void LANGUAGE sql AS $$SELECT$$;
CREATE FUNCTION fn_union_eco_enabled(uuid) RETURNS boolean LANGUAGE sql AS $$SELECT false$$;
CREATE FUNCTION fn_union_setting(uuid,text,numeric) RETURNS numeric LANGUAGE sql AS $$SELECT 1::numeric$$;
CREATE FUNCTION fn_union_settlement_conservation_assert(uuid,timestamptz,timestamptz,jsonb,jsonb,jsonb) RETURNS jsonb LANGUAGE sql AS $$SELECT '{}'::jsonb$$;
CREATE FUNCTION fn_union_mark_period_settled(uuid,timestamptz,timestamptz) RETURNS void LANGUAGE sql AS $$INSERT INTO effects VALUES(5,0)$$;
CREATE FUNCTION fn_union_weekly_rakeback_close(uuid,timestamptz,timestamptz) RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO effects VALUES(1,90); RETURN (SELECT result FROM fixture WHERE stage=1); END$$;
CREATE FUNCTION fn_settle_round2_club_to_agents(uuid,timestamptz,timestamptz) RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO effects VALUES(2,50); RETURN (SELECT result FROM fixture WHERE stage=2); END$$;
CREATE FUNCTION fn_settle_round3_agents_to_players(uuid,timestamptz,timestamptz) RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO effects VALUES(3,25); RETURN (SELECT result FROM fixture WHERE stage=3); END$$;
CREATE FUNCTION fn_union_issue_weekly_invoices(uuid,timestamptz,timestamptz,boolean) RETURNS jsonb LANGUAGE plpgsql AS $$BEGIN INSERT INTO effects VALUES(4,0); RETURN (SELECT result FROM fixture WHERE stage=4); END$$;
CREATE SCHEMA cron;
CREATE TABLE cron.job(jobname text PRIMARY KEY,schedule text,command text);
CREATE FUNCTION cron.schedule(text,text,text) RETURNS bigint LANGUAGE plpgsql AS $$BEGIN INSERT INTO cron.job VALUES($1,$2,$3) ON CONFLICT(jobname) DO UPDATE SET schedule=excluded.schedule,command=excluded.command; RETURN 1; END$$;
